// Cloudflare entry point: the OpenNext app, plus a cron that keeps the demo database alive.
//
// Free FalkorDB Cloud instances are stopped after a day without use and deleted after seven.
// Every 10 minutes the cron:
//   1. writes a ping (activity, so the instance isn't stopped as idle);
//   2. if the database can't be reached, signs in to FalkorDB Cloud and starts the instance
//      (needs FALKOR_CLOUD_EMAIL, FALKOR_CLOUD_PASSWORD, FALKOR_CLOUD_INSTANCE);
//   3. if the demo templates are missing, reseeds them.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as app } from "./.open-next/worker.js";
import { FalkorDB } from "falkordb";
// @ts-expect-error -- plain JS module shared with `pnpm seed`
import { seed } from "./scripts/seed.mjs";

type Env = { FALKORDB_URL?: string; FALKOR_CLOUD_EMAIL?: string; FALKOR_CLOUD_PASSWORD?: string; FALKOR_CLOUD_INSTANCE?: string };

const FREE = "https://api.omnistrate.cloud/2022-09-01-00/resource-instance/sp-JvkxkPhinN/falkordb/v1/prod/falkordb-free-customer-hosted/falkordb-free-falkordb-customer-hosted-model-omnistrate-multi-tenancy/free";
const TEMPLATES = ["tpl__weft", "tpl__weft_live", "tpl__weft_meta"];

const timeout = <T>(p: Promise<T>, ms: number) =>
  Promise.race([p, new Promise<never>((_, no) => setTimeout(() => no(new Error(`timed out after ${ms}ms`)), ms))]);

async function pingAndRepair(url: string) {
  const db = await timeout(FalkorDB.connect({ url }), 8000);
  try {
    await db.selectGraph("weft_keepalive").query("MERGE (p:Ping {id:1}) SET p.at = $at", { params: { at: new Date().toISOString() } });
    const graphs = await db.list();
    if (TEMPLATES.some((t) => !graphs.includes(t))) {
      console.log("keepalive: demo templates missing, reseeding");
      await seed(db);
    }
  } finally {
    await db.close();
  }
}

async function startInstance(env: Env) {
  if (!env.FALKOR_CLOUD_EMAIL || !env.FALKOR_CLOUD_PASSWORD || !env.FALKOR_CLOUD_INSTANCE) {
    console.error("keepalive: database unreachable and FalkorDB Cloud credentials are not set, can't start it");
    return;
  }
  const signin = await fetch("https://app.falkordb.cloud/api/signin", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ email: env.FALKOR_CLOUD_EMAIL, password: env.FALKOR_CLOUD_PASSWORD }),
  });
  const token = signin.headers.getSetCookie().join(";").match(/omnistrate_token=([^;]+)/)?.[1];
  if (!token) throw new Error(`FalkorDB Cloud sign-in failed (${signin.status})`);
  const headers = { Cookie: `omnistrate_token=${token}` };
  const desc = await fetch(`${FREE}/${env.FALKOR_CLOUD_INSTANCE}`, { headers });
  const status = desc.ok ? ((await desc.json()) as { status?: string }).status : `describe ${desc.status}`;
  console.log(`keepalive: instance ${env.FALKOR_CLOUD_INSTANCE} is ${status}`);
  if (status === "RUNNING" || status === "STARTING" || status === "DEPLOYING") return;
  const start = await fetch(`${FREE}/${env.FALKOR_CLOUD_INSTANCE}/start`, { method: "POST", headers });
  console.log(`keepalive: start requested → ${start.status}`);
}

export default {
  fetch: app.fetch,
  async scheduled(_event: unknown, env: Env) {
    if (!env.FALKORDB_URL) return;
    try {
      await pingAndRepair(env.FALKORDB_URL);
    } catch (e) {
      console.error("keepalive: ping failed:", e instanceof Error ? e.message : e);
      await startInstance(env);
    }
  },
};

// @ts-expect-error -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
